  return(0);
 } </code></pre>The output of this program is ________ . (answer in integer) <br>Note: Assume that the program compiles and runs successfully.

Consider the following C program:
<pre><code>
#include &lt;stdio.h&gt;

int main(){
    int a;
    int arr[5] = {30,50,10};
    int *ptr;
    ptr = &arr[0] + 1;
    a = *ptr;
    (*ptr)++;
    ptr++;
    printf("%d", a + (*ptr) + arr[1]);
    return 0;
}
</code></pre>
The output of the above program is ___________. (Answer in integer)

Consider the following C program:
<pre><code>
#include &lt;stdio.h&gt;

void stringcopy(char *, char *);

int main(){
    char a[30] = "@#Hello World!";
    stringcopy(a, a + 2);
    printf("%s\n", a);
    return 0;
}

void stringcopy(char *s, char *t) {
    while(*t)
        *s++ = *t++;
}
</code></pre>

